function headerToolMegaItemsForClient(site: Site, tools: SectionBlockInstance[], spanishXby: boolean): HeaderToolMegaItem[] {
  return tools.map((tool, index) => {
    const title = storefrontPaidToolBlockValue(tool, "title", spanishXby ? "herramienta IA" : "AI photo tool");
    const category = blockValue(tool, "category", "Photo AI");
    return {
      id: instanceKey(tool, index, "header_tool"),
      title,
      href: toolActionHref(site, blockValue(tool, "href", "/tools"), tool.id, title),
      category,
      categoryTitle: blockValue(tool, "categoryTitle", category)
    };
  });
}

function headerVideoGenerationTopicsForClient(site: Site, categories: VideoThemeCategory[], themes: VideoTheme[]): HeaderVideoGenerationTopic[] {
  if (site.id !== "site_dreamshoot") return [];
  const categoriesBySlug = new Map(categories.map((category) => [category.slug, category]));
  const categoriesById = new Map(categories.map((category) => [category.id, category]));
  const parentDefinitionsBySlug = new Map<string, (typeof mydreamshootsVideoGenerationParentCategories)[number]>(
    mydreamshootsVideoGenerationParentCategories.map((category) => [category.slug, category])
  );
  const themesBySlug = new Map(themes.filter((theme) => theme.status === "active").map((theme) => [theme.slug, theme]));
  return mydreamshootsVideoGenerationCategories
    .filter((definition) => isMydreamshootsCurrentVideoMenuSlug(definition.slug))
    .flatMap((definition) => {
      const category = categoriesBySlug.get(definition.slug);
      if (category && category.status !== "active") return [];
      const theme = themesBySlug.get(definition.slug);
      if (!category && !theme) return [];
      const configuredParent = category?.parent ?? (category?.parentId ? categoriesById.get(category.parentId) : undefined);
      const parentSlug = configuredParent?.slug ?? parentVideoGenerationCategorySlugForChild(definition.slug);
      const parentDefinition = parentSlug ? parentDefinitionsBySlug.get(parentSlug) : undefined;
      return [{
        id: category?.id ?? theme?.id ?? `video_topic_${definition.slug}`,
        slug: definition.slug,
        label: category?.label ?? definition.label,
        href: hrefFor(site, videoGenerationCreatePath(definition.slug)),
        imageUrl: theme?.imageUrl ?? undefined,
        parentSlug,
        parentLabel: configuredParent?.label ?? parentDefinition?.label,
        parentSortOrder: configuredParent?.sortOrder ?? parentDefinition?.sortOrder,
        sortOrder: category?.sortOrder ?? definition.sortOrder
      }];
    });
}

function groupedVideoGenerationTopicsForServer(topics: HeaderVideoGenerationTopic[]) {
  const groups = new Map<string, { slug: string; label: string; sortOrder: number; topics: HeaderVideoGenerationTopic[] }>();
  topics.forEach((topic, index) => {
    const slug = topic.parentSlug || "video-generation";
    const label = topic.parentLabel || "AI Video Generation";
    const existing = groups.get(slug) ?? { slug, label, sortOrder: topic.parentSortOrder ?? index, topics: [] };
    existing.label = topic.parentLabel || existing.label;
    existing.sortOrder = Math.min(existing.sortOrder, topic.parentSortOrder ?? existing.sortOrder);
    existing.topics.push(topic);
    groups.set(slug, existing);
  });
  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      topics: [...group.topics].sort((left, right) => (left.sortOrder ?? 0) - (right.sortOrder ?? 0) || left.label.localeCompare(right.label))
    }))
    .filter((group) => group.topics.length > 0)
    .sort((left, right) => left.sortOrder - right.sortOrder || left.label.localeCompare(right.label));
}

