function sortedByShowcaseSlugs<T>(items: T[], selectedSlugs: string[], slugFor: (item: T) => string, fallbackSortFor?: (item: T) => number): T[] {
  const priorities = new Map(selectedSlugs.map((slug, index) => [dreamshootCategorySlug(slug), index]));
  return items
    .map((item, index) => ({ item, index }))
    .sort((a, b) => {
      const aPriority = priorities.get(dreamshootCategorySlug(slugFor(a.item))) ?? Number.POSITIVE_INFINITY;
      const bPriority = priorities.get(dreamshootCategorySlug(slugFor(b.item))) ?? Number.POSITIVE_INFINITY;
      if (aPriority !== bPriority) return aPriority - bPriority;
      const aFallback = fallbackSortFor?.(a.item) ?? a.index;
      const bFallback = fallbackSortFor?.(b.item) ?? b.index;
      if (aFallback !== bFallback) return aFallback - bFallback;
      return a.index - b.index;
    })
    .map(({ item }) => item);
}

function generationShowcaseImageForPack(site: Site, pack: CreativePack, excludeImages: string[] = []): string {
  const excluded = new Set([packImage(site, pack), ...excludeImages].map((image) => comparableImageUrl(image)).filter(Boolean));
  const safeHomepageImage = dreamshootHomepageSafeImageForPack(site, pack);
  if (safeHomepageImage && !excluded.has(comparableImageUrl(safeHomepageImage)) && !looksLikeCompositeShowcaseImageUrl(safeHomepageImage)) {
    return safeHomepageImage;
  }
  const gallery = uniqueImageUrlList((pack.galleryImages ?? []).map((image) => mediaAssetUrl(site, image)))
    .filter((image) => !excluded.has(comparableImageUrl(image)) && !isGeneratedDreamshootPackCoverUrl(image) && !looksLikeCompositeShowcaseImageUrl(image));
  return gallery.slice(2).find(Boolean) ?? gallery.find(Boolean) ?? packImage(site, pack);
}

function dreamshootHomepageSafeImageForPack(site: Site, pack: CreativePack): string {
  if (isAidreamcapesSite(site)) return "";
  const candidateSlugs = uniqueStringList([
    generationShowcaseThemeSlugForPack(pack),
    pack.categoryRecord?.slug ? dreamshootCategorySlug(pack.categoryRecord.slug) : "",
    pack.category ? dreamshootCategorySlug(pack.category) : "",
    pack.name ? dreamshootCategorySlug(pack.name) : ""
  ]);
  const safePath = candidateSlugs.map((slug) => dreamshootHomepageSafeShowcaseImagePathBySlug[slug]).find(Boolean);
  return safePath ? mediaAssetUrl(site, safePath) : "";
}

function generationShowcaseThemeSlugForPack(pack: CreativePack): string {
  return dreamshootCategorySlug(creativePackCollectionSlug(pack) || pack.categoryRecord?.slug || pack.category || pack.name || pack.id);
}

function generationShowcasePackDedupeKey(pack: CreativePack): string {
  return dreamshootCategorySlug(pack.id || generationShowcaseThemeSlugForPack(pack) || pack.name);
}

function creativePackMatchesShowcaseSlug(pack: CreativePack, slug: string): boolean {
  const normalizedSlug = dreamshootCategorySlug(slug);
  if (!normalizedSlug) return false;
  return [
    pack.categoryRecord?.parent?.slug,
    pack.categoryRecord?.parent?.label,
    pack.categoryRecord?.slug,
    pack.categoryRecord?.label,
    pack.category,
    pack.name,
    creativePackCollectionSlug(pack)
  ].filter(Boolean).map((value) => dreamshootCategorySlug(String(value))).includes(normalizedSlug);
}

function homepageShowcaseImageCardFromSlug(site: Site, slug: string, creativePacks: CreativePack[]): GenerationShowcaseImageCard | null {
  const normalizedSlug = dreamshootCategorySlug(slug);
  if (!normalizedSlug) return null;
  const matchingPack = creativePacks.find((pack) => pack.status === "active" && creativePackMatchesShowcaseSlug(pack, normalizedSlug));
  const parentMatches = dreamshootCategorySlug(matchingPack?.categoryRecord?.parent?.slug || "") === normalizedSlug;
  const categoryLabel = parentMatches
    ? matchingPack?.categoryRecord?.parent?.label
    : matchingPack?.categoryRecord?.label || matchingPack?.categoryRecord?.parent?.label;
  const imageUrl = matchingPack
    ? generationShowcaseImageForPack(site, matchingPack)
    : dreamshootShowcaseImagePath(site, normalizedSlug);
  if (!imageUrl || looksLikeCompositeShowcaseImageUrl(imageUrl)) return null;
  return {
    id: `homepage-showcase-${normalizedSlug}`,
    slug: normalizedSlug,
    title: categoryLabel || matchingPack?.name || dreamshootCategoryLabel(normalizedSlug),
    imageUrl,
    meta: categoryLabel || dreamshootCategoryLabel(normalizedSlug)
  };
}

function generationShowcasePackPriorityIndex(pack: CreativePack, selectedImageSlugs: string[]): number {
  const themeSlug = generationShowcaseThemeSlugForPack(pack);
  const directIndex = selectedImageSlugs.findIndex((slug) => dreamshootCategorySlug(slug) === themeSlug);
  if (directIndex >= 0) return directIndex;
  const matchedIndex = selectedImageSlugs.findIndex((slug) => creativePackMatchesShowcaseSlug(pack, slug));
  return matchedIndex >= 0 ? matchedIndex : Number.POSITIVE_INFINITY;
}

function generationShowcasePriorityImageCardFromSlug(
  site: Site,
  slug: string,
  creativePacks: CreativePack[],
  claimedPackKeys: Set<string>,
  excludeImages: string[] = []
): GenerationShowcaseImageCard | null {
  const normalizedSlug = dreamshootCategorySlug(slug);
  if (!normalizedSlug) return null;
  const excludedImages = new Set(excludeImages.map((image) => comparableImageUrl(image)).filter(Boolean));
  const matchingPack = creativePacks.find((pack) => !claimedPackKeys.has(generationShowcasePackDedupeKey(pack)) && creativePackMatchesShowcaseSlug(pack, normalizedSlug));
  const card = homepageShowcaseImageCardFromSlug(site, normalizedSlug, matchingPack ? [matchingPack] : creativePacks);
  if (!card?.imageUrl || excludedImages.has(comparableImageUrl(card.imageUrl))) return null;
  if (matchingPack) claimedPackKeys.add(generationShowcasePackDedupeKey(matchingPack));
  return {
    ...card,
    id: matchingPack?.id || card.id
  };
}

function generationShowcaseCardFromPack(site: Site, pack: CreativePack, excludeImages: string[] = []): GenerationShowcaseImageCard {
  const slug = dreamshootCategorySlug(pack.categoryRecord?.slug || pack.category || pack.name);
  return {
    id: pack.id,
    slug,
    title: pack.name || pack.categoryRecord?.label || dreamshootCategoryLabel(pack.category || slug),
    imageUrl: generationShowcaseImageForPack(site, pack, excludeImages),
    meta: pack.categoryRecord?.label ?? pack.categoryRecord?.parent?.label ?? dreamshootCategoryLabel(pack.category || pack.name)
  };
}

function creativePackCategoryMatchScore(pack: CreativePack, category: CreativePackCategory): number {
  const categorySlug = dreamshootCategorySlug(category.slug || category.label);
  const directSlugs = [
    pack.categoryRecord?.slug,
    pack.category,
    pack.name,
    creativePackCollectionSlug(pack)
  ].filter(Boolean).map((value) => dreamshootCategorySlug(String(value)));
  if (pack.categoryRecord?.id && String(pack.categoryRecord.id) === category.id) return 0;
  if (directSlugs.includes(categorySlug)) return 1;
  if (pack.categoryRecord?.parent?.id && String(pack.categoryRecord.parent.id) === category.id) return 20;
  if (dreamshootCategorySlug(pack.categoryRecord?.parent?.slug || "") === categorySlug) return 21;
  return creativePackMatchesCategory(pack, category) ? 40 : Number.POSITIVE_INFINITY;
}

function creativePacksSortedForCategory(creativePacks: CreativePack[], category: CreativePackCategory): CreativePack[] {
  return creativePacks
    .map((pack, index) => ({ pack, index, score: creativePackCategoryMatchScore(pack, category) }))
    .filter((item) => item.pack.status === "active" && Number.isFinite(item.score))
    .sort((a, b) => a.score - b.score || (a.pack.categoryRecord?.sortOrder ?? 9999) - (b.pack.categoryRecord?.sortOrder ?? 9999) || a.index - b.index)
    .map(({ pack }) => pack);
}

function _generationShowcaseCardFromCategory(site: Site, category: CreativePackCategory, creativePacks: CreativePack[], excludeImages: string[] = []): GenerationShowcaseImageCard | null {
  const slug = dreamshootCategorySlug(category.slug || category.label);
  const rootAidreamcapesCategory = isAidreamcapesSite(site) && !isSpanishXbySite(site) && isAidreamcapesRootCategorySlug(slug);
  const relatedPacks = creativePacksSortedForCategory(creativePacks, category);
  const matchingPack = relatedPacks[0];
  const categoryImage = category.imageUrl ? mediaAssetUrl(site, category.imageUrl) : "";
  const imageUrl = rootAidreamcapesCategory
    ? aidreamcapesHomepageCategoryShowcaseImagePath(site, slug) || categoryImage
    : matchingPack
      ? generationShowcaseImageForPack(site, matchingPack, [...(categoryImage ? [categoryImage] : []), ...excludeImages])
      : categoryImage || dreamshootShowcaseImagePath(site, slug);
  if (!imageUrl) return null;
  return {
    id: category.id,
    slug,
    title: category.label,
    imageUrl,
    meta: category.parent?.label ?? category.label
  };
}

function generationShowcaseCardsFromSources<T>(
  sources: T[],
  cardForSource: (source: T, excludeImages: string[]) => GenerationShowcaseImageCard | null
): GenerationShowcaseImageCard[] {
  const usedImages: string[] = [];
  return sources
    .map((source) => {
      const card = cardForSource(source, usedImages);
      if (card?.imageUrl) usedImages.push(card.imageUrl);
      return card;
    })
    .filter((card): card is GenerationShowcaseImageCard => Boolean(card));
}

function generationShowcaseImageCardsForSite(site: Site, creativePacks: CreativePack[], selectedImageSlugs: string[]): GenerationShowcaseImageCard[] {
  const activePacks = creativePacks.filter((pack) => pack.status === "active");
  const uniqueSelectedImageSlugs = uniqueStringList(selectedImageSlugs.map((slug) => dreamshootCategorySlug(slug)));
  const seenPackKeys = new Set<string>();
  const uniquePacks = activePacks.filter((pack) => {
    const key = generationShowcasePackDedupeKey(pack);
    if (!key || seenPackKeys.has(key)) return false;
    seenPackKeys.add(key);
    return true;
  });
  const claimedPackKeys = new Set<string>();
  const usedImages: string[] = [];
  const priorityCards = uniqueSelectedImageSlugs
    .map((slug) => {
      const card = generationShowcasePriorityImageCardFromSlug(site, slug, uniquePacks, claimedPackKeys, usedImages);
      if (card?.imageUrl) usedImages.push(card.imageUrl);
      return card;
    })
    .filter((card): card is GenerationShowcaseImageCard => Boolean(card));
  const orderedPacks = uniquePacks
    .filter((pack) => !claimedPackKeys.has(generationShowcasePackDedupeKey(pack)))
    .map((pack, index) => ({
      pack,
      index,
      priority: generationShowcasePackPriorityIndex(pack, uniqueSelectedImageSlugs)
    }))
    .sort((a, b) => {
      if (a.priority !== b.priority) return a.priority - b.priority;
      const aSort = a.pack.categoryRecord?.sortOrder ?? 9999;
      const bSort = b.pack.categoryRecord?.sortOrder ?? 9999;
      if (aSort !== bSort) return aSort - bSort;
      return a.index - b.index;
    })
    .map(({ pack }) => pack);
  const packCards = orderedPacks
    .map((pack) => {
      const card = generationShowcaseCardFromPack(site, pack, usedImages);
      if (card?.imageUrl) usedImages.push(card.imageUrl);
      return card;
    })
    .filter((card): card is GenerationShowcaseImageCard => Boolean(card));
  const rawCards = [...priorityCards, ...packCards];
  const selectedFallbackCards = generationShowcaseCardsFromSources(uniqueSelectedImageSlugs, (slug) => homepageShowcaseImageCardFromSlug(site, slug, activePacks));
  const cards = rawCards.length ? rawCards : selectedFallbackCards;
  const seen = new Set<string>();
  const seenImages = new Set<string>();
  const preserveThemeCards = uniqueSelectedImageSlugs.length === 0;
  return cards.filter((card) => {
    const key = generationShowcaseImageDedupeKey(site, card.id || card.slug);
    const imageKey = comparableImageUrl(card.imageUrl);
    if (!key || seen.has(key) || !imageKey || (!preserveThemeCards && seenImages.has(imageKey))) return false;
    seen.add(key);
    seenImages.add(imageKey);
    return Boolean(card.imageUrl);
  });
}

function generationShowcaseVideoCardsForSite(videoThemes: VideoTheme[], selectedVideoSlugs: string[], limit = Number.POSITIVE_INFINITY): GenerationShowcaseVideoCard[] {
  const activeVideoThemes = videoThemes.filter((theme) => theme.status === "active");
  const videoBySlug = new Map<string, VideoTheme>();
  activeVideoThemes.forEach((theme) => videoBySlug.set(dreamshootCategorySlug(theme.slug), theme));
  const selectedVideoThemes = selectedVideoSlugs
    .map((slug) => videoBySlug.get(dreamshootCategorySlug(slug)))
    .filter((theme): theme is VideoTheme => Boolean(theme));
  // Published theme snapshots can lag behind homepage settings. Keep the section
  // populated with active themes when configured slugs do not resolve at runtime.
  const orderedVideoThemes = selectedVideoSlugs.length && selectedVideoThemes.length
    ? selectedVideoThemes
    : activeVideoThemes;
  const seenVideoIds = new Set<string>();
  const videoCards = orderedVideoThemes
    .filter((theme) => {
      if (seenVideoIds.has(theme.id)) return false;
      seenVideoIds.add(theme.id);
      return Boolean((theme.galleryImages ?? []).find((item) => /\.(?:mp4|webm)(?:\?|#|$)/i.test(item)));
    })
    .map((theme, index) => {
      const videoUrl = (theme.galleryImages ?? []).find((item) => /\.(?:mp4|webm)(?:\?|#|$)/i.test(item)) ?? "";
      return {
        id: theme.id,
        slug: dreamshootCategorySlug(theme.slug),
        title: theme.name,
        posterUrl: theme.imageUrl || fallbackImageForSeed(`${theme.siteId}-${theme.slug}-poster`),
        videoUrl,
        meta: theme.category?.label ?? theme.name,
        index
      };
    });
  return Number.isFinite(limit) ? videoCards.slice(0, Math.max(1, Math.floor(limit))) : videoCards;
}

function aidreamcapesRootCategoryImageUrlsForSite(site: Site, creativePackCategories: CreativePackCategory[]): string[] {
  if (!isAidreamcapesSite(site) || isSpanishXbySite(site)) return [];
  const rootCategories = creativePackCategories.filter((category) => category.status === "active" && isAidreamcapesRootCategorySlug(category.slug || category.label));
  const rootCategoryImages = uniqueImageUrlList(
    sortedByShowcaseSlugs(
      rootCategories,
      [],
      (category) => category.slug || category.label,
      (category) => category.sortOrder
    ).map((category) => {
      const slug = dreamshootCategorySlug(category.slug || category.label);
      return aidreamcapesHomepageCategoryShowcaseImagePath(site, slug) || (category.imageUrl ? mediaAssetUrl(site, category.imageUrl) : "");
    })
  );
  if (rootCategoryImages.length) return rootCategoryImages;
  return aidreamcapesRootCategoryShowcaseSlugs.map((slug) =>
    mediaAssetUrl(site, `/assets/sites/site_aidreamcapes/fan-holiday-theme/categories/${slug}.webp?v=${aidreamcapesFanHolidayAssetVersion}`)
  );
}

function cleanStorefrontImageSrc(src: string): string {
  return src.trim().replace(/&amp;/g, "&").replace(/\\+$/g, "");
}

function imageFilename(src = ""): string {
  const cleanPath = cleanStorefrontImageSrc(src).split("?")[0]?.split("#")[0] ?? "";
  return cleanPath.split("/").filter(Boolean).pop()?.toLowerCase() ?? "";
}

function imageBasename(src = ""): string {
  return imageFilename(src).replace(/\.(png|jpe?g|webp|avif|svg)$/i, "");
}

