function manualAltForImage({ id, src }: { id?: string; src?: string }): string {
  const byFile = dreamshootManualImageAltByFile[imageBasename(src)];
  if (byFile) return byFile;
  const byBlock = id ? dreamshootManualImageAltByBlockId[id.trim().toLowerCase()] : "";
  return byBlock || "";
}

function preferDreamshootOptimizedImage(src: string): string {
  if (!src.startsWith("/assets/dreamshoot/")) return src;
  return src.replace(/\.png(\?.*)?$/i, (match, query = "") => `.webp${query}`);
}

function preferAidreamcapesPhotoAsset(src: string): string {
  const cleanSrc = cleanStorefrontImageSrc(src);
  const bareAidreamcapesPackMatch = cleanSrc.match(/^\/([a-z0-9-]+\.(?:png|webp|svg))(\?.*)?$/i);
  if (bareAidreamcapesPackMatch) {
    return preferAidreamcapesPhotoAsset(`/assets/sites/site_aidreamcapes/creative-packs/${bareAidreamcapesPackMatch[1]}${bareAidreamcapesPackMatch[2] ?? ""}`);
  }
  if (cleanSrc.includes("/assets/dreamshoot/brand/aidreamcapesai-logo-refined.svg")) {
    return "/assets/sites/site_aidreamcapes/brand/aidreamcapesai-logo-refined.svg?v=20260708c";
  }
  if (cleanSrc.includes("/assets/sites/site_aidreamcapes/brand/aidreamcapes-wordmark.svg")) {
    return "/assets/sites/site_aidreamcapes/brand/aidreamcapesai-logo-refined.svg?v=20260708c";
  }
  if (cleanSrc.includes("/assets/sites/site_aidreamcapes/creative-packs/travel-profile-stories.")) {
    return "/assets/sites/site_aidreamcapes/creative-packs/celestial-profile-stories.webp?v=20260715ai";
  }
  if (cleanSrc.includes("/assets/sites/site_aidreamcapes/creative-packs/storybook-headshots.")) {
    return "/assets/sites/site_aidreamcapes/creative-packs/celestial-profile-stories.webp?v=20260715ai";
  }
  if (cleanSrc.startsWith("/assets/aidreamcapes/")) {
    return "/assets/sites/site_aidreamcapes/creative-packs/dreamscape-portraits.webp?v=20260715ai";
  }
  if (!cleanSrc.startsWith("/assets/sites/site_aidreamcapes/creative-packs/")) return cleanSrc;
  const versionedSrc = cleanSrc.replace(/\.(?:png|jpe?g|svg)(\?.*)?$/i, ".webp$1");
  const [path, query = ""] = versionedSrc.split("?");
  const params = new URLSearchParams(query);
  params.set("v", "20260715ai");
  return `${path}?${params.toString()}`;
}

type StorefrontImageProps = {
  src: string;
  alt?: string;
  className?: string;
  width?: number;
  height?: number;
  sizes?: string;
  priority?: boolean;
  loading?: "eager" | "lazy";
  fetchPriority?: "high" | "low" | "auto";
  preview?: StorefrontImagePreview;
};

type StorefrontSafeImageProps = StorefrontImageProps & {
  imageClassName?: string;
};

type StorefrontImagePreview = false | {
  src?: string;
  title?: string;
  meta?: string;
};

function previewTitleFromAlt(alt: string): string {
  return alt.trim() || "Image preview";
}

function storefrontImagePreviewAttrs(src: string, alt: string, preview?: StorefrontImagePreview) {
  if (preview === false) return {};
  const previewSrc = preview?.src?.trim() || src;
  if (!previewSrc.trim()) return {};
  return {
    "aria-label": `View ${previewTitleFromAlt(preview?.title || alt)} full screen`,
    "data-dreamshoot-preview-meta": preview?.meta || "",
    "data-dreamshoot-preview-src": previewSrc,
    "data-dreamshoot-preview-title": previewTitleFromAlt(preview?.title || alt),
    "data-dreamshoot-showcase-preview": "image",
    role: "button",
    tabIndex: 0
  } as const;
}

function previewableImageClassName(className = "", preview?: StorefrontImagePreview): string {
  return preview === false ? className : `${className} cursor-zoom-in`.trim();
}

function canUseNextImage(src: string): boolean {
  return src.startsWith("/") && /\.(png|jpe?g|webp|avif)(\?|$)/i.test(src);
}

function fallbackAltFromImageSrc(src: string): string {
  const cleanPath = src.split("?")[0]?.split("#")[0] ?? "";
  const filename = cleanPath.split("/").filter(Boolean).pop() ?? "";
  if (cleanPath.includes("/site_aidreamcapes/fan-holiday-theme/")) {
    const basename = filename.replace(/\.(png|jpe?g|webp|avif|svg)$/i, "");
    const aidreamcapesFanHolidayAltBySlug: Record<string, string> = {
      "fan-scene-albums": "AIdreamcapes fan-scene album cover showing a private supporter portrait gallery for holiday and event keepsakes",
      "game-day-group-photos": "AIdreamcapes game-day group photo cover showing a private stadium crowd album for fan and holiday keepsakes",
      "premiere-style-portraits": "AIdreamcapes premiere-inspired portrait cover showing a private red-carpet style album for event keepsakes",
      "christmas-group-albums": "AIdreamcapes Christmas group album cover showing a private festive keepsake gallery for family celebrations",
      "thanksgiving-memory-sets": "AIdreamcapes Thanksgiving keepsake set cover showing a private holiday memory gallery for seasonal albums",
      "halloween-party-portraits": "AIdreamcapes Halloween party portrait cover showing a private costume-night album for seasonal keepsakes",
      "seasonal-celebration-photos": "AIdreamcapes seasonal celebration photo album cover showing a private holiday gallery with warm event lighting",
      "private-fan-scene-album": "AIdreamcapes private fan-scene album cover showing supporter-style portraits for a private holiday gallery",
      "game-day-group-portraits": "AIdreamcapes game-day group portraits cover showing a private stadium celebration album for event keepsakes",
      "premiere-flash-portraits": "AIdreamcapes premiere flash portrait cover showing a private event gallery with polished evening lighting",
      "christmas-group-album": "AIdreamcapes Christmas group album cover showing a private festive gallery for seasonal keepsakes",
      "thanksgiving-keepsake-table-set": "AIdreamcapes Thanksgiving keepsake table set cover showing a private holiday gallery for family memories",
      "halloween-party-portrait-set": "AIdreamcapes Halloween party portrait set cover showing a private costume-night gallery for seasonal keepsakes",
      "seasonal-celebration-photo-set": "AIdreamcapes seasonal celebration photo set cover showing a private holiday album scene with warm event lighting"
    };
    if (aidreamcapesFanHolidayAltBySlug[basename]) return aidreamcapesFanHolidayAltBySlug[basename];
    return `AIdreamcapes ${basename.replace(/-\d+$/g, "").replace(/-/g, " ")} cover showing a private fan and holiday album scene for storefront gallery browsing`;
  }
  if (cleanPath.includes("/site_aidreamcapes/creative-packs/")) {
    const aidreamcapesAltByFilename: Record<string, string> = {
      "coastal-getaways-v2.png": "Coastal Light Sets",
      "coastal-getaways-v2.webp": "Coastal Light Sets",
      "coastal-light-sets-cover.png": "Coastal Light Sets",
      "coastal-light-sets-cover.webp": "Coastal Light Sets",
      "scenic-overlooks-v2.png": "Scenic Outlooks",
      "scenic-overlooks-v2.webp": "Scenic Outlooks",
      "golden-hour-route-stories-cover.png": "Golden Hour Route Stories",
      "golden-hour-route-stories-cover.webp": "Golden Hour Route Stories",
      "road-trip-frames-v2.png": "Roadside Escape Frames",
      "road-trip-frames-v2.webp": "Roadside Escape Frames",
      "cinematic-travel.png": "Cinematic Travel Portraits",
      "cinematic-travel.webp": "Cinematic Travel Portraits",
      "itinerary-moodboards-v2.png": "Route Moodboards",
      "itinerary-moodboards-v2.webp": "Route Moodboards",
      "route-moodboards-cover.png": "Route Moodboards",
      "route-moodboards-cover.webp": "Route Moodboards",
      "postcard-social-sets-v2.png": "Postcard Story Sets",
      "postcard-social-sets-v2.webp": "Postcard Story Sets",
      "social-keepsakes.png": "Social Keepsakes",
      "social-keepsakes.webp": "Social Keepsakes",
      "island-resort-scenes-v2.png": "Island Balcony Scenes",
      "island-resort-scenes-v2.webp": "Island Balcony Scenes",
      "old-quarter-walks-cover.png": "Old Quarter Walks",
      "old-quarter-walks-cover.webp": "Old Quarter Walks",
      "cafe-street-story-studio.png": "Cafe Street Story Studio",
      "cafe-street-story-studio.webp": "Cafe Street Story Studio",
      "dreamscape-portraits.png": "Route Portrait Albums",
      "dreamscape-portraits.webp": "Route Portrait Albums",
      "destination-story.png": "Destination Story Portraits",
      "destination-story.webp": "Destination Story Portraits",
      "postcard-journey.png": "Postcard Journey Portraits",
      "postcard-journey.webp": "Postcard Journey Portraits",
      "mountain-trails.png": "Alpine Route Portraits",
      "mountain-trails.webp": "Alpine Route Portraits"
    };
    const mappedAlt = aidreamcapesAltByFilename[filename];
    if (mappedAlt) return mappedAlt;
  }
  const readable = filename
    .replace(/\.(png|jpe?g|webp|avif|svg)$/i, "")
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase())
    .trim();
  return readable ? `${readable} image` : "Storefront image";
}

function StorefrontImage({
  src,
  alt,
  className,
  width,
  height,
  sizes = "(max-width: 768px) 100vw, 33vw",
  priority = false,
  loading,
  fetchPriority,
  preview
}: StorefrontImageProps) {
  const resolvedSrc = withStorefrontPublicWatermarkCacheVersion(preferAidreamcapesPhotoAsset(src));
  const resolvedLoading = loading ?? (priority ? "eager" : "lazy");
  const resolvedFetchPriority = fetchPriority ?? (priority ? "high" : "low");
  const isLocalPublicAsset = resolvedSrc.startsWith("/assets/");
  const fallbackAlt = alt?.trim() || fallbackAltFromImageSrc(resolvedSrc);
  const resolvedAlt = manualImageAlt({ explicitAlt: alt, src: resolvedSrc, fallback: fallbackAlt });
  const previewAttrs = storefrontImagePreviewAttrs(resolvedSrc, resolvedAlt, preview);
  const resolvedClassName = previewableImageClassName(className, preview);
  if (isLocalPublicAsset || !canUseNextImage(resolvedSrc)) {
    return (
      <img
        alt={resolvedAlt}
        className={resolvedClassName}
        decoding={priority ? "sync" : "async"}
        fetchPriority={resolvedFetchPriority}
        height={height}
        loading={resolvedLoading}
        src={resolvedSrc}
        width={width}
        {...previewAttrs}
      />
    );
  }
  return (
    <NextImage
      alt={resolvedAlt}
      className={resolvedClassName}
      decoding={priority ? "sync" : "async"}
      fetchPriority={resolvedFetchPriority}
      fill
      loading={priority ? undefined : resolvedLoading}
      priority={priority}
      sizes={sizes}
      src={resolvedSrc}
      {...previewAttrs}
    />
  );
}

function decorativeImageBackgroundStyle(src: string): CSSProperties {
  return {
    backgroundImage: `url("${src.replace(/["\\]/g, "\\$&")}")`
  };
}

function StorefrontSafeImage({
  src,
  alt,
  className = "",
  imageClassName = "",
  sizes,
  priority,
  loading,
  fetchPriority,
  preview
}: StorefrontSafeImageProps) {
  const resolvedSrc = withStorefrontPublicWatermarkCacheVersion(preferAidreamcapesPhotoAsset(src));
  const safeAlt = manualImageAlt({ explicitAlt: alt, src: resolvedSrc, fallback: fallbackAltFromImageSrc(resolvedSrc) });
  return (
    <div className={`relative overflow-hidden ${className}`}>
      <StorefrontImage
        alt={safeAlt}
        className={`relative z-10 h-full w-full object-cover object-center ${imageClassName}`}
        fetchPriority={fetchPriority}
        loading={loading}
        preview={preview}
        priority={priority}
        sizes={sizes}
        src={resolvedSrc}
      />
    </div>
  );
}

type StorefrontNaturalImageProps = {
  src: string;
  alt: string;
  className?: string;
  imageClassName?: string;
  loading?: "eager" | "lazy";
  fetchPriority?: "high" | "low" | "auto";
  decoding?: "async" | "auto" | "sync";
  preview?: StorefrontImagePreview;
};

function StorefrontNaturalImage({
  src,
  alt,
  className = "",
  imageClassName = "",
  loading = "lazy",
  fetchPriority = "low",
  decoding = "async",
  preview
}: StorefrontNaturalImageProps) {
  const resolvedSrc = withStorefrontPublicWatermarkCacheVersion(preferAidreamcapesPhotoAsset(src));
  const safeAlt = manualImageAlt({ explicitAlt: alt, src: resolvedSrc, fallback: fallbackAltFromImageSrc(resolvedSrc) });
  const previewAttrs = storefrontImagePreviewAttrs(resolvedSrc, safeAlt, preview);
  return (
    <div className={`overflow-hidden ${previewableImageClassName(className, preview)}`} {...previewAttrs}>
      <img
        alt={safeAlt}
        className={`block h-auto w-full object-center ${imageClassName}`}
        decoding={decoding}
        fetchPriority={fetchPriority}
        loading={loading}
        src={resolvedSrc}
      />
    </div>
  );
}

function shouldPrioritizeStorefrontSectionImage(renderContext: RenderContext, sectionType: string, index = 0): boolean {
  if (index !== 0) return false;
  if (renderContext.pagePath === "/") return sectionType === "hero_plus" || sectionType === "image_banner";
  return true;
}

function featuredPackImageShape(block: SectionBlockInstance): "wide" | "tall" | "square" {
  const shape = blockValue(block, "shape", "square").toLowerCase();
  if (/(wide|landscape|banner|cover|horizontal)/.test(shape)) return "wide";
  if (/(tall|portrait|story|vertical)/.test(shape)) return "tall";
  return "square";
}

function shouldAlignFeaturedPackGrid(blocks: SectionBlockInstance[]): boolean {
  const shapes = new Set(blocks.map(featuredPackImageShape));
  return shapes.size <= 1;
}

function normalizedFeaturedPackCollectionSlug(value: string): string {
  const slug = dreamshootCategorySlug(value);
  return slug && slug !== "all" ? slug : "";
}

function collectionSlugFromHrefValue(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return "";
  let pathname = trimmed;
  if (/^https?:\/\//i.test(trimmed)) {
    try {
      pathname = new URL(trimmed).pathname;
    } catch {
      pathname = trimmed;
    }
  }
  const parts = pathname.split(/[?#]/)[0]?.split("/").filter(Boolean) ?? [];
  if (parts[0] === "collections") return parts[1] ? normalizedFeaturedPackCollectionSlug(decodeURIComponent(parts[1])) : "";
  if (parts[0] === "ai-image-generation") return parts[2] ? normalizedFeaturedPackCollectionSlug(decodeURIComponent(parts[2])) : parts[1] ? normalizedFeaturedPackCollectionSlug(decodeURIComponent(parts[1])) : "";
  return "";
}

function featuredPackSlugRefs(value: string): string[] {
  return uniqueStringList(
    value
      .split(/[|,;\n]+/g)
      .flatMap((part) => {
        const fromHref = collectionSlugFromHrefValue(part);
        const slug = fromHref || normalizedFeaturedPackCollectionSlug(part);
        return slug ? [slug] : [];
      })
  );
}

function featuredPackImageSlugRefs(imageUrl: string): string[] {
  const trimmed = imageUrl.trim();
  if (!trimmed) return [];
  let pathname = trimmed.split("#")[0]?.split("?")[0] ?? "";
  if (/^https?:\/\//i.test(trimmed)) {
    try {
      pathname = new URL(trimmed).pathname;
    } catch {
      pathname = trimmed;
    }
  }
  const segments = decodeURIComponent(pathname).split("/").filter(Boolean);
  const fileName = segments.at(-1) ?? "";
  const parent = segments.at(-2) ?? "";
  const fileStem = fileName.replace(/\.[a-z0-9]+$/i, "");
  const strippedStem = fileStem.replace(/(?:-\d+)+$/g, "").replace(/-cover$/i, "");
  return uniqueStringList([parent, fileStem, strippedStem].map(normalizedFeaturedPackCollectionSlug).filter(Boolean));
}

function featuredPackCategorySlugTokens(category: CreativePackCategory): string[] {
  return uniqueStringList([category.id, category.slug, category.label].map((value) => normalizedFeaturedPackCollectionSlug(value ?? "")).filter(Boolean));
}

function featuredPackCreativePackSlugTokens(pack: CreativePack): string[] {
  return uniqueStringList([
    pack.id,
    pack.categoryRecord?.id,
    pack.categoryRecord?.slug,
    pack.categoryRecord?.label,
    pack.category,
    pack.name,
    pack.aiAppSlug,
    creativePackCollectionSlug(pack)
  ].map((value) => normalizedFeaturedPackCollectionSlug(value ?? "")).filter(Boolean));
}

function featuredPackCollectionHrefForSlug(
  slug: string,
  creativePacks: CreativePack[],
  creativePackCategories: CreativePackCategory[]
): string {
  const normalizedSlug = normalizedFeaturedPackCollectionSlug(slug);
  if (!normalizedSlug) return "";
  const category = creativePackCategories.find(
    (candidate) => candidate.status === "active" && featuredPackCategorySlugTokens(candidate).includes(normalizedSlug)
  );
  if (category) return collectionHref(category.slug || category.label || category.id);
  const pack = creativePacks.find(
    (candidate) => candidate.status === "active" && featuredPackCreativePackSlugTokens(candidate).includes(normalizedSlug)
  );
  return pack ? creativePackCollectionHref(pack) : "";
}

function featuredPackTileHref(
  site: Site,
  block: SectionBlockInstance,
  creativePacks: CreativePack[],
  creativePackCategories: CreativePackCategory[],
  fallbackHref: string
): string {
  const explicitRefs = featuredPackSlugRefs(blockValue(block, "collectionSlug", ""));
  for (const slug of explicitRefs) {
    const href = featuredPackCollectionHrefForSlug(slug, creativePacks, creativePackCategories);
    if (href) return hrefFor(site, href);
  }
  if (explicitRefs[0]) return hrefFor(site, collectionHref(explicitRefs[0]));

  const legacyHref = blockValue(block, "href", "");
  const legacyHrefSlug = collectionSlugFromHrefValue(legacyHref);
  if (legacyHrefSlug) {
    const href = featuredPackCollectionHrefForSlug(legacyHrefSlug, creativePacks, creativePackCategories);
    return hrefFor(site, href || collectionHref(legacyHrefSlug));
  }

  const inferredRefs = uniqueStringList([
    ...featuredPackImageSlugRefs(blockValue(block, "imageUrl", "")),
    ...featuredPackSlugRefs(block.id),
    ...featuredPackSlugRefs(blockValue(block, "label", ""))
  ]);
  for (const slug of inferredRefs) {
    const href = featuredPackCollectionHrefForSlug(slug, creativePacks, creativePackCategories);
    if (href) return hrefFor(site, href);
  }

  return hrefFor(site, legacyHref || fallbackHref || "/collections");
}

function runtimeCollectionImage(
  site: Site,
  section: SectionInstance,
  explicit: string | undefined,
  fallbackSeed: string
): string {
  const candidate = explicit || setting(section, "imageUrl", "");
  return candidate ? mediaAssetUrl(site, candidate) : fallbackImageForSeed(fallbackSeed);
}

function assetPreviewUrl(site: Site, assetIdOrKey: string | undefined, runtime?: ThemeRuntimeData): string {
  const lookup = assetIdOrKey?.trim();
  if (!lookup) return "";
  const runtimeAsset = runtime?.assets.find((asset) => asset.id === lookup || asset.previewUrl === lookup);
  if (runtimeAsset) {
    return runtimeAsset.previewUrl;
  }
  return mediaAssetUrl(site, lookup);
}

function albumPreviewUrl(site: Site, album: ThemeRuntimeData["albums"][number], runtime?: ThemeRuntimeData): string {
  const byCover = assetPreviewUrl(site, album.coverAssetId, runtime);
  if (byCover) return byCover;

  if (album.sourceJobId) {
    const jobOutput = runtime?.assets.find((asset) => asset.role === "output" && asset.jobId === album.sourceJobId);
    if (jobOutput) return assetPreviewUrl(site, jobOutput.id, runtime);
  }

  const creativePackMatch = runtime?.assets.find((asset) => asset.role === "output");
  if (creativePackMatch) return assetPreviewUrl(site, creativePackMatch.id, runtime);

  return fallbackImageForSeed(`${site.slug}-${album.id}-album`);
}

function isRuntimeAlbum(item: ThemeRuntimeData["albums"][number] | ThemeRuntimeData["assets"][number]): item is ThemeRuntimeData["albums"][number] {
  return "outputCount" in item;
}

function priceMetaNumber(price: SiteProduct["prices"][number] | undefined, key: string, fallback: number): number {
  const raw = price?.metadata?.[key];
  if (typeof raw === "number") return raw;
  if (typeof raw === "string" && raw.trim()) {
    const parsed = Number(raw);
    if (Number.isFinite(parsed)) return parsed;
  }
  return fallback;
}

function priceMetaString(price: SiteProduct["prices"][number] | undefined, key: string, fallback: string): string {
  const raw = price?.metadata?.[key];
  if (typeof raw === "string" && raw.trim()) return raw;
  if (typeof raw === "number" || typeof raw === "boolean") return String(raw);
  return fallback;
}

function priceMetaBool(price: SiteProduct["prices"][number] | undefined, key: string, fallback: boolean): boolean {
  const raw = price?.metadata?.[key];
  if (typeof raw === "boolean") return raw;
  if (typeof raw === "string") return raw === "true";
  return fallback;
}

function importedThemeBadge(schema: ReturnType<typeof getSectionSchema>) {
  if (schema.source === "saas-theme1" || schema.source === "saas-theme") {
    return "Theme section";
  }
  return schema.label;
}

function firstImage(section: SectionInstance): string {
  const settingImage = ["imageUrl", "mediaAssetId", "src", "image", "mobile_src", "bg_image"].map((key) => setting(section, key)).find(Boolean);
  if (settingImage) return settingImage;
  for (const block of sectionBlocks(section)) {
    const image = ["imageUrl", "mediaAssetId", "src", "image", "mobile_src", "bg_image"].map((key) => blockValue(block, key)).find(Boolean);
    if (image) return image;
  }
  return "";
}

function settingListBlocks(
  section: SectionInstance,
  key: string,
  fallback: string[],
  mapper: (item: string, index: number) => SectionBlockInstance
): SectionBlockInstance[] {
  const blocks = sectionBlocks(section);
  if (blocks.length) return blocks;
  return listSetting(section, key, fallback).map(mapper);
}

function routedSitePath(site: Site, path = "/"): string {
  const normalizedPath = !path || path === "/" ? "/" : path.startsWith("/") ? path : `/${path}`;
  const basePath = (site as RoutedSite).__storefrontBasePath;
  if (typeof basePath === "string") {
    if (!basePath) return normalizedPath;
    return normalizedPath === "/" ? basePath : `${basePath}${normalizedPath}`;
  }
  return hostAwareSitePath(site, normalizedPath);
}

function hrefFor(site: Site, href: string): string {
  if (!href) return routedSitePath(site);
  if (href === "javascript:void(0);") return "#";
  if (/^(mailto|tel|sms):/i.test(href)) return href;
  if (href.startsWith("/app/create") && href.includes("#")) {
    const [rawPath, rawHash = ""] = href.split("#", 2);
    const anchor = rawHash.trim();
    const allowedAnchors = new Set(["step-upload", "step-create", "step-video", "source-photos", "review-request"]);
    if (allowedAnchors.has(anchor)) {
      const separator = rawPath.includes("?") ? "&" : "?";
      return routedSitePath(site, `${rawPath}${separator}nextHash=${encodeURIComponent(anchor)}`);
    }
  }
  const pairedStore = usesAiGenerationPublicRoutes(site);
  const primaryMyDreamShoots = isPrimaryMydreamshootsCapabilitySite(site);
  if (href.startsWith("http")) {
    try {
      const url = new URL(href);
      const targetHost = cleanHost(url.host);
      const siteHost = cleanHost(site.primaryDomain);
      const sameStoreHost = Boolean(siteHost && targetHost.replace(/^www\./, "") === siteHost.replace(/^www\./, ""));
      if (pairedStore && sameStoreHost) {
        const normalizedPath = shortPolicyPath(
          url.pathname === "/help"
            ? "/faq"
            : url.pathname === "/how-it-works" || url.hash === "#workflow"
              ? "/workflow"
              : url.pathname
        );
        const canonicalPath = normalizedPath === "/collections" || normalizedPath.startsWith("/collections/") || normalizedPath === "/ai-image-generation" || normalizedPath.startsWith("/ai-image-generation/")
          ? canonicalCollectionHrefForSite(site, normalizedPath)
          : normalizedPath;
        const normalizedHash = url.hash === "#workflow" ? "" : url.hash;
        return `${routedSitePath(site, canonicalPath)}${url.search}${normalizedHash}`;
      }
      const normalizedPolicyPath = shortPolicyPath(url.pathname);
      if (normalizedPolicyPath !== url.pathname) {
        url.pathname = normalizedPolicyPath;
        return url.toString();
      }
    } catch {
      return href;
    }
    return href;
  }
  if (pairedStore && (href === "/workflow" || href === "/how-it-works")) return routedSitePath(site, "/workflow");
  if (pairedStore && href === "/help") return routedSitePath(site, "/faq");
  if (href === "#workflow" || href === "/#workflow") return routedSitePath(site, "/workflow");
  if (href === "#faq" || href === "/#faq") return routedSitePath(site, "/faq");
  const normalizedPolicyPath = shortPolicyPath(href);
  if (normalizedPolicyPath !== href) return routedSitePath(site, normalizedPolicyPath);
  if (href.startsWith("/app?") && href.endsWith("#create")) return routedSitePath(site, `/app/create?${href.slice("/app?".length, -"#create".length)}`);
  if (href === "/app#create") return routedSitePath(site, "/app/create");
  if (href === "/app#upload_1") return routedSitePath(site, "/app/upload");
  if (href === "/app#progress_1") return routedSitePath(site, "/app/jobs/progress");
  if (href === "/app#album_1") return routedSitePath(site, "/album");
  if (href.startsWith("#")) return href;
  const legacyPrefix = `/site/${site.slug}`;
  if (href === legacyPrefix) return routedSitePath(site, "/");
  if (href.startsWith(`${legacyPrefix}/`)) return routedSitePath(site, href.slice(legacyPrefix.length));
  if (href.startsWith("/collections?")) {
    const category = new URLSearchParams(href.slice(href.indexOf("?") + 1)).get("category") ?? "";
    return routedSitePath(site, canonicalCollectionHrefForSite(site, collectionHref(category)));
  }
  if (href === "/collections" || href.startsWith("/collections/") || href === "/ai-image-generation" || href.startsWith("/ai-image-generation/")) return routedSitePath(site, canonicalCollectionHrefForSite(site, href));
  if (href.startsWith("/cart?")) return routedSitePath(site, href);
  if (primaryMyDreamShoots && (href === "/tools" || href.startsWith("/tools/"))) {
    const toolSlug = href.slice("/tools/".length).split(/[?#]/)[0] ?? "";
    if (!toolSlug || toolSlug === "video-ai") return routedSitePath(site, "/ai-video-generation");
    if (isMydreamshootsVideoGenerationSlug(toolSlug)) return routedSitePath(site, publicVideoGenerationPathForSite(site, toolSlug));
    const imageSlugByLegacyTool: Record<string, string> = {
      headshot: "headshot",
      "creator-portrait": "portrait-photo",
      "creator-portraits": "portrait-photo",
      "world-cup-fan-photos": "soccer",
      "cyberpunk-portrait": "cyberpunk",
      "gala-photo": "gala-photo",
      "noir-portrait": "mafia",
      "anime-avatar": "avatar",
      "nature-adventure": "travel",
      "fashion-editorial": "street-style",
      "product-lifestyle": "background-changer",
      "background-changer": "background-changer",
      "background-remover": "background-remover",
      "magic-eraser": "magic-eraser",
      "photo-enhancer": "photo-enhancer",
      "portrait-retouch": "portrait-retouch",
      "unblur-image": "unblur-image",
      "color-correction": "color-correction",
      "old-photo-restoration": "old-photo-restoration",
      "edit-by-prompt": "edit-by-prompt",
      "magic-upscaler": "photo-enhancer",
      "virtual-try-on": "virtual-try-on"
    };
    return routedSitePath(site, imageSlugByLegacyTool[toolSlug] ? `/ai-image-generation/${imageSlugByLegacyTool[toolSlug]}` : "/ai-image-generation");
  }
  if ((href === "/tools/image-studio" || href === "/tools/ai-image-studio") && isPrimaryMydreamshootsCapabilitySite(site)) {
    return routedSitePath(site, "/ai-image-generation");
  }
  return routedSitePath(site, href);
}

function blogArticleBodyHtmlForSite(site: Site, html: string): string {
  return html.replace(/\bhref=(["'])(\/(?!\/)[^"']*)\1/gi, (match, quote: string, href: string) => {
    const routedHref = hrefFor(site, href);
    return match.replace(`${quote}${href}${quote}`, `${quote}${routedHref}${quote}`);
  });
}

function hrefForPage(site: Site, href: string, pagePath: string): string {
  const normalizedPagePath = !pagePath || pagePath === "/" ? "/" : pagePath.startsWith("/") ? pagePath : `/${pagePath}`;
  if (href === "#workflow" || href === "/#workflow" || href === "#faq" || href === "/#faq") return hrefFor(site, href);
  if (normalizedPagePath === "/" && href.startsWith("#")) return href;
  if (normalizedPagePath === "/" && href.startsWith("/#")) return href.slice(1);
  return hrefFor(site, href);
}

function formActionFor(site: Site, href: string): string {
  const actionHref = hrefFor(site, href);
  const queryStart = actionHref.indexOf("?");
  return queryStart >= 0 ? actionHref.slice(0, queryStart) : actionHref;
}

function hiddenSearchParamsFromHref(href: string): { name: string; value: string }[] {
  const queryStart = href.indexOf("?");
  if (queryStart < 0) return [];
  return Array.from(new URLSearchParams(href.slice(queryStart + 1)).entries()).map(([name, value]) => ({ name, value }));
}

function isExternalHttpHrefForSite(site: Site, href: string): boolean {
  if (!href.startsWith("http://") && !href.startsWith("https://")) return false;
  try {
    const urlHost = cleanHost(new URL(href).host);
    const siteHost = cleanHost(site.primaryDomain);
    const comparableUrlHost = urlHost.replace(/^www\./, "");
    const comparableSiteHost = siteHost.replace(/^www\./, "");
    return Boolean(comparableUrlHost && comparableSiteHost && comparableUrlHost !== comparableSiteHost);
  } catch {
    return false;
  }
}

function collectionHref(category: string): string {
  const slug = dreamshootCategorySlug(category);
  return !slug || slug === "all" || slug === "todo" || slug === "todos" ? "/collections" : `/collections/${slug}`;
}

function publicStorefrontToken(value: string, prefixes: string[]): string {
  let next = dreamshootCategorySlug(value);
  for (const prefix of prefixes) {
    const normalizedPrefix = dreamshootCategorySlug(prefix);
    if (next.startsWith(`${normalizedPrefix}-`)) next = next.slice(normalizedPrefix.length + 1);
  }
  return next;
}

function publicCreativePackToken(pack: CreativePack): string {
  return publicStorefrontToken(pack.id || pack.name, ["pack_mydreamshoots_xby", "pack_aidreamcapes_xby", "pack_dreamshoot", "pack_aidreamcapes"]);
}

function publicProductToken(product: SiteProduct): string {
  return publicStorefrontToken(product.id || product.name, ["prod_mydreamshoots_xby", "prod_aidreamcapes_xby", "prod_dreamshoot", "prod_aidreamcapes"]);
}

function publicPriceToken(price: SiteProduct["prices"][number], product?: SiteProduct): string {
  const raw = publicStorefrontToken(price.id || price.label, ["price_mydreamshoots_xby", "price_aidreamcapes_xby", "price_dreamshoot", "price_aidreamcapes"]);
  const productToken = product ? publicProductToken(product) : "";
  return productToken && raw.startsWith(`${productToken}-`) ? raw : raw;
}

function publicCartHref(site: Site, product: SiteProduct | undefined, price: SiteProduct["prices"][number] | undefined): string {
  const params = new URLSearchParams();
  if (product) params.set("product", isSpanishXbySite(site) ? publicProductToken(product) : product.id);
  if (price) params.set("price", isSpanishXbySite(site) ? publicPriceToken(price, product) : price.id);
  const query = params.toString();
  return hrefFor(site, query ? `/cart?${query}` : "/cart");
}

